<?php
namespace App\Http\Controllers;
use App\Models\{ProductSku,Order,OrderItem,Payment,Address,Coupon}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class CheckoutController extends Controller {
 private function data(Request $r){$cart=$r->session()->get('cart',[]);if(!$cart)return [[],0];$skus=ProductSku::with('product')->whereIn('sku_id',array_keys($cart))->get()->keyBy('sku_id');$subtotal=0;foreach($cart as $id=>$qty){if(!isset($skus[$id])||$qty<1||$qty>$skus[$id]->stock_quantity)abort(422,'Cart contains unavailable stock.');$subtotal += $skus[$id]->price*$qty;}return [$skus,$subtotal];}
 public function create(Request $r){[$items,$subtotal]=$this->data($r);return view('store.checkout',['items'=>$items,'subtotal'=>$subtotal,'addresses'=>auth()->user()->addresses()->get()]);}
 public function store(Request $r){[$items,$subtotal]=$this->data($r);$d=$r->validate(['address_line_1'=>'required|max:255','address_line_2'=>'nullable|max:255','city'=>'required|max:100','state'=>'nullable|max:100','postal_code'=>'required|max:20','country'=>'required|max:100','payment_method'=>'required|in:Cash on Delivery,Bkash,Nagad,Card','coupon_code'=>'nullable|string|max:50']);$coupon=null;$discount=0;if($d['coupon_code']){$coupon=Coupon::where('code',$d['coupon_code'])->where('is_active',1)->whereDate('expiry_date','>=',now())->first();if(!$coupon)return back()->withErrors(['coupon_code'=>'Invalid or expired coupon.'])->withInput();if($coupon->min_order_amount>$subtotal)return back()->withErrors(['coupon_code'=>'Minimum order amount not met.'])->withInput();if($coupon->usage_limit!==null&&$coupon->used_count>=$coupon->usage_limit)return back()->withErrors(['coupon_code'=>'Coupon usage limit reached.'])->withInput();$discount=$coupon->discount_type==='Percentage'?min($subtotal,$subtotal*$coupon->discount_value/100):min($subtotal,$coupon->discount_value);}$shipping=($subtotal-$discount)>0?60:0;$tax=0;$total=$subtotal-$discount+$shipping+$tax;$order=null;DB::transaction(function()use($r,$d,$items,$subtotal,$discount,$shipping,$tax,$total,$coupon,&$order){$address=Address::create(['user_id'=>auth()->id(),'address_type'=>'Shipping','address_line_1'=>$d['address_line_1'],'address_line_2'=>$d['address_line_2']??null,'city'=>$d['city'],'state'=>$d['state']??null,'postal_code'=>$d['postal_code'],'country'=>$d['country']]);$order=Order::create(['user_id'=>auth()->id(),'coupon_id'=>$coupon?->coupon_id,'order_number'=>'ORD-'.now()->format('YmdHis').'-'.Str::upper(Str::random(5)),'subtotal'=>$subtotal,'discount_amount'=>$discount,'shipping_cost'=>$shipping,'tax_amount'=>$tax,'total_amount'=>$total,'status'=>'Pending']);foreach($items as $id=>$sku){$qty=$r->session()->get("cart.$id");$locked=ProductSku::where('sku_id',$id)->lockForUpdate()->first();if(!$locked||$locked->stock_quantity<$qty)throw new \RuntimeException('Stock changed. Please retry.');$locked->decrement('stock_quantity',$qty);$order->items()->create(['sku_id'=>$id,'quantity'=>$qty,'price'=>$locked->price]);}Payment::create(['order_id'=>$order->order_id,'amount'=>$total,'payment_method'=>$d['payment_method'],'status'=>$d['payment_method']==='Cash on Delivery'?'Pending':'Pending','payment_date'=>now()]);$coupon?->increment('used_count');});$r->session()->forget('cart');return redirect()->route('orders.show',$order)->with('success','Order placed successfully.');}
}
